// Generated by AI
using UnityEngine;

/// <summary>
/// The categories of waste the backpack can absorb and sort.
/// </summary>
public enum WasteType
{
    Plastic,
    Metal,
    Glass,
    Organic,
    Electronic
}

/// <summary>
/// Put this on every waste prefab. It tells the vacuum what kind of waste it is.
/// </summary>
[RequireComponent(typeof(Rigidbody))]
public class WasteItem : MonoBehaviour
{
    [SerializeField] private WasteType wasteType;
    [SerializeField] private bool freezeUntilAbsorbed = true;

    public WasteType Type => wasteType;
    public Rigidbody Body { get; private set; }

    // Prevents the same item from being stored twice in the same frame.
    public bool IsCollected { get; set; }

    private void Awake()
    {
        Body = GetComponent<Rigidbody>();

        // Keeps the waste where it was placed until the vacuum takes it.
        if (freezeUntilAbsorbed && Body != null)
        {
            Body.isKinematic = true;
        }
    }

    /// <summary>
    /// Call this from your vacuum script when starting absorption so physics/movement work as intended.
    /// </summary>
    public void ReleaseFreeze()
    {
        if (Body != null)
        {
            Body.isKinematic = false;
        }
    }
}